p-implement-roving-focus-for-a-toolbar.starter:
type Orientation = 'horizontal' | 'vertical';

/** The index to focus after key: arrows on the orientation's axis move and wrap, Home and End jump,
 *  other keys return current; -1 when there are no items. */
export function nextIndex(key: string, current: number, count: number, orientation: Orientation): number {
  throw new Error('Not implemented');
}

p-implement-roving-focus-for-a-toolbar.solution:
type Orientation = 'horizontal' | 'vertical';
export function nextIndex(key: string, current: number, count: number, orientation: Orientation): number {
  if (count <= 0) return -1;
  const [prev, next] = orientation === 'horizontal' ? ['ArrowLeft', 'ArrowRight'] : ['ArrowUp', 'ArrowDown'];
  switch (key) {
    case next:
      return (current + 1) % count;
    case prev:
      return (current - 1 + count) % count;
    case 'Home':
      return 0;
    case 'End':
      return count - 1;
    default:
      return current;
  }
}

